     if (activity.slots < 1) return 'DADOS_INVALIDOS';
     if (activity.slots > room.capacity) return 'VAGAS_ACIMA_DA_CAPACIDADE';
     if (_roomConflict(activity)) return 'CONFLITO_DE_SALA';
